  k.y += px(5); ImRect b({k.x, k.y}, {k.x + k.w, k.y + px(12)}); k.d->AddRectFilled(b.Min, b.Max, u(przezr(M.txt, .1f)), px(3)); float wm = k.w * r.model_gb / std::max(.1, r.total_gb), ws = k.w * (r.used_gb - r.model_gb) / std::max(.1, r.total_gb);
