  if (hover(b)) { float mxp = ImGui::GetIO().MousePos.x - b.Min.x; int ktory = mxp < wm ? 0 : mxp < wm + ws ? 1 : 2; const char* n[3] = {t("ram_model"), t("ram_sys"), t("ram_free")}; double v[3] = {r.model_gb, r.used_gb - r.model_gb, r.total_gb - r.used_gb}; tipJuz(std::string("RAM · ") + n[ktory], n1(v[ktory]) + " GB\n-\n" + t("ram_model") + "\t" + n1(v[0]) + " GB\n" + t("ram_sys") + "\t" + n1(v[1]) + " GB\n" + t("ram_free") + "\t" + n1(v[2]) + " GB"); A.pod.el = "wartosc"; A.pod.wartosc = std::string("RAM ") + n[ktory] + ": " + n1(v[ktory]) + " GB"; }
  k.y += px(12 + 5); kv(k, std::string(t("ram_model")) + " / " + t("ram_sys"), n1(r.model_gb) + " / " + n1(r.used_gb - r.model_gb) + " GB", L("Memory reserved by the running model / by everything else.", "Pamięć zarezerwowana przez działający model / przez całą resztę."));
