OpisStanu opisStanu() {
  OpisStanu o; o.kl = "idle"; if (A.s.llm.empty()) return o; auto& m = A.s.llm[0]; const Aktywne* a = m.active ? &*m.active : nullptr;
  if (m.status == "starting") { o.lab = t("st_load"); o.kl = "read"; if (m.ladowanie) { auto& l = *m.ladowanie; o.info = std::string(t("loaded")) + " " + n1(l.wczytano_mb / 1024) + " / " + n1(l.rozmiar_mb / 1024) + " GB (" + I(l.pct) + "%) · VRAM " + n1(l.vram_mb / 1024) + " GB"; } }
  else if (!m.up_ok) { o.lab = t("st_err"); o.kl = "bad"; }
  else if (a) { const char* lab = "st_gen"; std::string kl = "ans"; if (a->phase == "reading") { lab = "st_read"; kl = "read"; } else if (a->phase == "thinking") { lab = "st_think"; kl = "think"; } else if (a->phase == "answering") { lab = "st_ans"; kl = "ans"; } else if (a->phase == "tool") { lab = "st_tool"; kl = "tool"; } else if (a->phase == "compact") { lab = "st_comp"; kl = "comp"; } o.lab = t(lab); o.kl = kl;
    std::string kn = a->kind == "chat" ? t("k_chat") : a->kind == "compact" ? t("k_compact") : a->kind == "agent" ? t("k_agent") : a->kind; o.info = std::string(t("request")) + " #" + std::to_string(a->id) + " · " + kn + (m.queued ? std::string(" · ") + t("queue") + " " + std::to_string(m.queued) : "") + (a->eff.empty() ? "" : std::string(" · ") + t("effort") + ": " + a->eff) + (a->tools.empty() ? "" : " · " + a->tools[0]);
    std::string lo1 = t("c_in"), lo2 = t("c_out"); for (auto* s : {&lo1, &lo2}) { for (auto& c : *s) c = tolower((unsigned char)c); }
    o.c = lo1 + " " + n0(a->in) + " " + t("tok") + (a->cache ? " (cache " + n0(a->cache) + ")" : "") + " · " + lo2 + " " + n0(a->out) + " " + t("tok") + (a->phase == "reading" ? " · prefill " + n0(a->proc) + " · PP " + n0(a->ptps) + " t/s" : " · TG " + (a->inst ? n1(a->inst) : std::string("…")) + " · avg " + (jest(a->avg) ? n1(a->avg) : std::string("…")) + " t/s") + " · " + n1(a->el) + " s"; }
  else { o.lab = t("st_idle"); o.info = t("waits"); }
  return o;
}
const std::vector<Panel>& definicjePaneli() { static std::vector<Panel> p = {{"gpu", "p_gpu"}, {"cpu", "p_cpu"}, {"ram", "p_ram"}, {"disks", "p_disks", true}, {"llm", "p_llm"}, {"models", "p_models", true}, {"energy", "p_energy"}}; return p; }
std::string podpisPanelu(const std::string& id) {
  if (id == "models") { int n = 0, r = 0; for (auto& m : A.s.models) { n++; r += m.status != "stopped"; } return std::to_string(r) + " / " + std::to_string(n); }
  if (id == "energy") { auto& e = A.s.energia; return n0(e.teraz_w_gniazdko) + " W · " + t("e_today") + " " + n2(e.dzis_kwh) + " kWh · " + t("e_month") + " " + n2(e.miesiac_kwh) + " kWh"; }
  if (id == "disks") return std::to_string(dyskiWidoczne().size());
  return "";
}
